import Anthropic from "@anthropic-ai/sdk";
import { z } from "zod";
import { forStructuredOutput } from "@/lib/ai/tagging-schema";

// Text-only re-rank (CLAUDE.md Decision 3, mode 2): the model sees tag DESCRIPTIONS,
// never images. It returns the best 3 with a look name + one-sentence "why".

export type DescItem = {
  category: string;
  subcategory?: string | null;
  colors: string[];
  /**
   * The signals the deterministic half already scores on. The model saw none of
   * them until 2026-08-15, which had two costs: the pattern-clash term could
   * only ORDER the shortlist while the model picked blind to it and was free to
   * choose the one combo with two loud pieces; and the "why" — the product's
   * differentiator — described fabric it was guessing at from a subcategory
   * name. Text costs nothing here (CLAUDE.md Decision 3: never images), and an
   * accurate sentence is the whole point of the call.
   */
  material?: string | null;
  texture?: string | null;
  pattern?: string | null;
};

/**
 * Unremarkable values are omitted rather than printed.
 *
 * "solid" on every line is noise that buries the one patterned piece, and
 * "flat" says nothing a reader does not already assume. What is left is
 * exactly what should influence the choice.
 */
function describeItem(it: DescItem): string {
  const notes = [
    it.material?.toLowerCase(),
    it.texture && it.texture !== "Flat" ? it.texture.toLowerCase() : null,
    it.pattern && it.pattern !== "solid" ? it.pattern : null,
  ].filter(Boolean);
  const detail = [it.colors.join("/"), ...notes].filter(Boolean).join(", ");
  return `${it.subcategory ?? it.category}${detail ? ` (${detail})` : ""}`;
}

export function describeCombos(combos: DescItem[][]): string {
  return combos.map((c, i) => `${i}. ` + c.map(describeItem).join(" + ")).join("\n");
}

/**
 * Display budget for a look name — comfortably fits the "≤4 words" the prompt
 * asks for ("The Impeccable Charcoal Layer" = 29) with room to spare.
 */
export const NAME_MAX = 40;

/**
 * Clamp a name to NAME_MAX on a word boundary.
 *
 * A name is decoration; the "why" is the product. This is a `transform`, not a
 * `.max()`, on purpose: the cap is never enforced on the model — CLAUDE.md's
 * `forStructuredOutput` strips `maxLength` because the API 400s on it — so a
 * hard bound here existed only as a post-hoc throw that failed the ENTIRE
 * generation and surfaced as "Couldn't reach the stylist". Repair, don't reject.
 */
export function clampName(raw: string): string {
  const s = raw.trim();
  if (s.length <= NAME_MAX) return s;
  const cut = s.slice(0, NAME_MAX);
  const lastSpace = cut.lastIndexOf(" ");
  return (lastSpace > 0 ? cut.slice(0, lastSpace) : cut).trimEnd();
}

// The WIRE shape — what we ask the model for. Kept transform-free because
// `z.toJSONSchema` cannot represent a transform ("Transforms cannot be
// represented in JSON Schema"); the repair belongs on the way in, not the way out.
const PickShape = z.object({
  combo_index: z.number().int(),
  name: z.string().min(1),
  why: z.string().min(1),
});

// Sanitised JSON Schema for Anthropic's output_config.format (strips min/max keywords
// that would 400 — real bounds re-enforced by RerankSchema.parse after the call).
export const rerankJsonSchema = forStructuredOutput(
  z.toJSONSchema(z.object({ picks: z.array(PickShape).length(3) })),
) as Record<string, unknown>;

/** The most looks a daily drop ever shows. */
export const MAX_PICKS = 3;

// The PARSE shape — same fields, plus the name repair.
//
// `.min(1)`, NOT `.length(3)`. The count is never enforced ON the model —
// `forStructuredOutput` strips minItems/maxItems because the API 400s on them —
// so an exact-3 rule existed only as a post-hoc throw, and a closet with fewer
// than three viable combos failed the ENTIRE generation as "Couldn't reach the
// stylist". That is a lie: the stylist answered, with everything the wardrobe
// could give. It bites hardest right after onboarding's "capture your first
// five", which is the magic moment. Repair, don't reject — the same stance as
// `clampName`. An empty array is still an error; there is nothing to show.
export const RerankSchema = z.object({
  picks: z.array(PickShape.extend({ name: z.string().min(1).transform(clampName) })).min(1),
});
export type RerankResult = z.infer<typeof RerankSchema>;

/**
 * The variety instruction.
 *
 * "Pick the best 3" alone produces three versions of one outfit: the model is
 * optimising a single notion of "best", and the candidates handed to it are
 * ranked, so the top of the list is naturally near-identical. Asking for the
 * best 3 without asking for three DIFFERENT ones gets exactly what it asks for.
 */
export const RERANK_VARIETY_RULE =
  "The three must be genuinely different outfits, not variations of one: no two may share the same top, and no two may share the same bottom. If the candidates cannot give you three that differ, prefer variety over a marginally higher-scoring repeat.";

type Pick = { combo_index: number; name: string; why: string };

/**
 * Drop picks that reuse a combo the model already chose.
 *
 * The schema checks the array LENGTH, never that the indices differ, so a model
 * returning [4, 4, 7] rendered the same outfit twice. Repair rather than reject
 * — the same stance as `clampName` above: a duplicated index should cost the
 * user one look, not the whole generation.
 *
 * Returning fewer than three is fine and deliberate: the daily drop already
 * tolerates a variable count (`saveDailyLooks` is delete-then-insert for exactly
 * this reason), and two real looks beat three where two are the same.
 */
export function dedupePicks(picks: Pick[], comboCount?: number): Pick[] {
  const seen = new Set<number>();
  return picks.filter((p) => {
    // An index outside the shortlist used to fall back to the FIRST combo, so
    // two bad indices rendered the same outfit twice — duplicates that survive
    // de-duplication because the indices themselves differ. Drop them instead.
    if (comboCount != null && (p.combo_index < 0 || p.combo_index >= comboCount)) return false;
    if (seen.has(p.combo_index)) return false;
    seen.add(p.combo_index);
    return true;
  });
}

/**
 * Everything that stands between the model's answer and the screen: drop
 * repeats and out-of-range indices, then cap at MAX_PICKS. The cap lives here
 * rather than in the schema so an over-eager model costs the user nothing.
 */
export function finalisePicks(picks: Pick[], comboCount?: number, want = MAX_PICKS): Pick[] {
  return dedupePicks(picks, comboCount).slice(0, Math.max(1, want));
}

/**
 * The deterministic stand-in for the model, used by the e2e suite.
 *
 * ⚠️ It lives HERE, inside `rerank`, rather than in a test file — the whole
 * deterministic pipeline (candidates → rank → diversify → layout →
 * persistence → render) still runs, and the code path under test stays the
 * code path that ships. A stub mounted from the test would prove the test
 * works, not that the app does.
 *
 * Enabled only by `FITCHECK_STUB_AI=1`, which is set in CI and nowhere else.
 * Returns the first `want` combos in order, so assertions about WHICH looks
 * appear are stable across runs — the real model's names and "why" sentences
 * differ every time and cannot be asserted at all.
 */
export function stubbedRerank(comboCount: number, want: number): RerankResult {
  const picks = Array.from({ length: Math.min(want, comboCount) }, (_, i) => ({
    combo_index: i,
    name: `Test Look ${i + 1}`,
    why: `A deterministic stand-in for look ${i + 1}, used only when FITCHECK_STUB_AI is set.`,
  }));
  return { picks };
}

export async function rerank(args: {
  combos: DescItem[][];
  aesthetic: string[];
  occasion: string;
  weatherLabel: string;
  /**
   * The temperature the candidates were CHOSEN for — the peak of the window
   * this occasion is worn in (`planningTempFor`), not the current reading.
   *
   * Both call sites passed the current temperature until 2026-08-15, so the
   * model was reasoning about a different day from the one the shortlist was
   * built for. That is how a look chose a cable knit and then explained it as
   * "warmth appropriate for the mild weather" — the sentence was true of the
   * temperature it was given and false of the outfit it was describing.
   */
  tempC: number;
  /** What the thermometer says right now, when it differs enough to matter. */
  nowC?: number;
  /**
   * How many looks to return. Defaults to the full daily set; a regenerate on a
   * day where a look has already been WORN asks for fewer, because the worn one
   * is pinned and still counts toward the day's three. "Today's Looks" is a set
   * of three — the index tabs are 01/02/03 and a fourth does not fit at 390px.
   */
  want?: number;
}): Promise<RerankResult> {
  const want = Math.max(1, Math.min(args.want ?? MAX_PICKS, MAX_PICKS));

  // Checked before the client is constructed, so CI needs no ANTHROPIC_API_KEY
  // and spends nothing. See `stubbedRerank`.
  if (process.env.FITCHECK_STUB_AI === "1") {
    return {
      picks: finalisePicks(stubbedRerank(args.combos.length, want).picks, args.combos.length, want),
    };
  }

  // Say the peak out loud when the day still has to climb into it, or the model
  // reasons about the morning and writes a sentence the outfit contradicts.
  const climbing = args.nowC != null && args.tempC - args.nowC >= 3;
  const weather = climbing
    ? `${args.weatherLabel}, ${args.nowC}°C now, rising to ${args.tempC}°C — these outfits are chosen for the warmest part of the day, so describe them for that, not for the current chill`
    : `${args.weatherLabel}, ${args.tempC}°C`;
  const prompt = `You are a personal stylist. The user's aesthetic is ${
    args.aesthetic.join(", ") || "understated, modern menswear"
  }. Occasion: ${args.occasion}. Weather: ${weather}.
Each piece is listed as: name (colours, fabric, weave, pattern) — fabric and weave are given where known, and a pattern is named only when the piece is not plain. Prefer outfits whose fabrics suit the temperature above, and avoid putting two patterned pieces together.
Here are candidate outfits (already filtered and scored), one per line:
${describeCombos(args.combos)}

Pick the best ${want}. ${RERANK_VARIETY_RULE}

For each return: its combo_index; a short evocative NAME (≤4 words and at most ${NAME_MAX} characters, e.g. "The Off-Duty Camel"); and ONE warm, specific sentence ("why") that references the colours/pieces (e.g. "the camel knit warms the grey trousers and picks up the loafers"). Only claim a fabric or weave that is actually listed for that piece. Return exactly ${want} pick${want === 1 ? "" : "s"}, each with a DIFFERENT combo_index.`;

  const client = new Anthropic(); // lazy: keeps this module importable in tests without a key
  const res = await client.messages.create({
    model: "claude-haiku-4-5",
    max_tokens: 700,
    output_config: { format: { type: "json_schema", schema: rerankJsonSchema } },
    messages: [{ role: "user", content: prompt }],
  });
  const text = res.content.find((b) => b.type === "text")?.text ?? "{}";
  const parsed = RerankSchema.parse(JSON.parse(text));
  // The prompt asks for distinct picks; this guarantees it. A model that repeats
  // an index costs the user one look, not a duplicated outfit on the screen.
  return { ...parsed, picks: finalisePicks(parsed.picks, args.combos.length, want) };
}

import { z } from "zod";

// MATERIALS and TEXTURES are defined HERE rather than imported from
// lib/closet/vocab.ts: vocab derives CATEGORIES/SEASONS from this schema, so
// importing back would be a cycle. `vocab.ts` re-exports these two, and remains
// the module every UI surface reads from.

/**
 * What the garment is made of.
 *
 * `Merino wool` is listed separately from `Wool` on purpose: they behave
 * differently in heat, and one undifferentiated "wool" is exactly the
 * conflation that makes warmth rules wrong. Warmth is decided by fibre AND
 * construction — see TEXTURES.
 */
export const MATERIALS = [
  "Cotton",
  "Wool",
  "Merino wool",
  "Cashmere",
  "Linen",
  "Silk",
  "Denim",
  "Leather",
  "Suede",
  "Faux leather",
  "Canvas",
  "Corduroy",
  "Tweed",
  "Fleece",
  "Shearling",
  "Down",
  "Polyester",
  "Acrylic",
  "Nylon",
  "Viscose",
  "Modal",
  "Lyocell",
  "Stainless steel",
  "Gold",
  "Silver",
  "Rubber",
  "Other",
] as const;

/**
 * How the fabric is built — knit structure and surface finish. A separate
 * dimension from material: a ribbed merino knit and a flat merino shirt share a
 * material and read completely differently, in both warmth and formality.
 *
 * `Other` is the escape hatch, and the one value deliberately shared with
 * MATERIALS. Without it a required `z.enum` forces the model to mislabel rather
 * than admit it cannot tell from a photo.
 */
export const TEXTURES = [
  "Flat",
  "Ribbed",
  "Cable knit",
  "Waffle",
  "Chunky knit",
  "Fine knit",
  "Brushed",
  "Fleece-back",
  "Twill",
  "Herringbone",
  "Quilted",
  "Pile",
  "Open knit",
  "Terry",
  "Seersucker",
  "Other",
] as const;

/**
 * The colour vocabulary — the ONE list, enforced on the model.
 *
 * This was `z.array(z.string())` until 2026-08-06, while the edit screens
 * offered a 21-swatch picker: the model could write "khaki" or "off-white",
 * which `colorHex()` could not render a swatch for and the user could not
 * reselect. `lib/generator/color.ts` had meanwhile widened its families with
 * ~23 free-form names (sand, oatmeal, cognac, terracotta, onyx…) to catch that
 * output, so three vocabularies were drifting apart at once.
 *
 * Constrained here for the same reason MATERIALS and TEXTURES are: the model is
 * constrained, not asked nicely. `lib/closet/vocab.ts` attaches the hex and the
 * neutral flag to these names, and a test pins the two lists together.
 */
export const COLOR_NAMES = [
  // Achromatic
  "black", "charcoal", "grey", "silver", "white", "ivory", "cream",
  // Warm neutrals / earths
  "stone", "sand", "beige", "taupe", "khaki", "camel", "tan", "caramel", "chocolate", "brown",
  // Blues
  "navy", "indigo", "denim", "blue", "sky", "teal",
  // Greens
  "olive", "sage", "forest", "green", "mint",
  // Reds / pinks
  "burgundy", "maroon", "red", "rust", "terracotta", "coral", "pink",
  // Purples
  "purple", "lavender", "plum",
  // Yellows / oranges
  "mustard", "yellow", "gold", "orange",
] as const;

// Categories + seasons match the prototype (Title case) so tags line up with
// the closet filters and the generator.
export const TagSchema = z.object({
  category: z.enum(["Tops", "Bottoms", "Outerwear", "Shoes", "Accessories", "Fragrance"]),
  subcategory: z.string().min(1),
  colors: z.array(z.enum(COLOR_NAMES)).min(1).max(3),
  pattern: z.enum(["solid", "striped", "check", "print", "other"]),
  material: z.enum(MATERIALS),
  texture: z.enum(TEXTURES),
  formality: z.number().int().min(1).max(5),
  seasons: z.array(z.enum(["Spring", "Summer", "Autumn", "Winter"])).min(1),
});
export type Tags = z.infer<typeof TagSchema>;

// Anthropic structured outputs (output_config.format) only accept type/enum/shape
// keywords — NOT the numeric (minimum/maximum/multipleOf), string (min/maxLength),
// or array (min/maxItems/uniqueItems) validation keywords that z.toJSONSchema()
// emits from our .min()/.max()/.int() refinements. Sending them 400s. We strip them
// here; the exact bounds are still enforced after the call by TagSchema.parse().
const UNSUPPORTED_JSON_SCHEMA_KEYWORDS = new Set([
  "minimum", "maximum", "exclusiveMinimum", "exclusiveMaximum", "multipleOf",
  "minLength", "maxLength",
  "minItems", "maxItems", "uniqueItems",
]);

export function forStructuredOutput(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(forStructuredOutput);
  if (node && typeof node === "object") {
    const out: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(node)) {
      if (UNSUPPORTED_JSON_SCHEMA_KEYWORDS.has(key)) continue;
      out[key] = forStructuredOutput(value);
    }
    // Structured outputs require every object to forbid extra properties.
    if (out.type === "object" && !("additionalProperties" in out)) {
      out.additionalProperties = false;
    }
    return out;
  }
  return node;
}

// Zod 4 native JSON Schema, sanitised for Anthropic's output_config.format.
export const taggingJsonSchema = forStructuredOutput(
  z.toJSONSchema(TagSchema),
) as Record<string, unknown>;
===== TAG-ITEM
"use server";

import Anthropic from "@anthropic-ai/sdk";
import { taggingJsonSchema } from "./tagging-schema";
import { parseTagText } from "./parse-tags";

const client = new Anthropic(); // reads ANTHROPIC_API_KEY (server-only)

const PROMPT = `You are an expert menswear cataloguer. Tag the SINGLE item in the photo — a \
garment, a pair of shoes, or an accessory. Its background may be removed. Judge only from what \
is visible and fill every field.

category — the family it belongs to:
  · Tops: shirts, tees, polos, knits, sweaters, hoodies
  · Bottoms: trousers, chinos, jeans, shorts, skirts
  · Outerwear: coats, overcoats, blazers, jackets
  · Shoes: all footwear
  · Accessories: belts, bags, hats, scarves, ties, watches, jewellery, sunglasses
subcategory — the specific type, in menswear vocabulary (e.g. "Oxford shirt", "Chinos", \
"Penny loafers", "Chelsea boots", "Leather belt", "Field watch"). Be precise.
colors — the 1-3 dominant colours, most-dominant first, common names (navy, charcoal, cream, \
tan, olive, burgundy). Ignore small logos and hardware.
pattern — one of: solid, striped, check, print, other.
material — the main material, from this list ONLY: Cotton, Wool, Merino wool, Cashmere, Linen, \
Silk, Denim, Leather, Suede, Faux leather, Canvas, Corduroy, Tweed, Fleece, Shearling, Down, \
Polyester, Acrylic, Nylon, Viscose, Modal, Lyocell, Stainless steel, Gold, Silver, Rubber, Other. \
For a blend, name the DOMINANT fibre. Pick the closest; use Other only if none fit.
texture — how the fabric is BUILT, from this list ONLY: Flat, Ribbed, Cable knit, Waffle, \
Chunky knit, Fine knit, Brushed, Fleece-back, Twill, Herringbone, Quilted, Pile, Open knit, Terry, \
Seersucker, Other. This is separate from material: a ribbed merino knit and a flat merino shirt \
share a material but wear very differently. Use Flat for smooth woven cloth with no visible \
structure, and Other only if none fit.
formality — 1 very casual (tees, sneakers, hoodies) up to 5 formal (suits, dress shoes, silk \
ties). 3 is smart-casual: chinos, oxford shirts, loafers, clean minimal sneakers.
seasons — every season the item genuinely suits (wool coat → Autumn, Winter; linen shirt → \
Spring, Summer; a plain cotton tee → all four).

Return ONLY the structured tags.`;

export async function tagItem(
  cutoutBase64: string,
  mediaType: "image/png" | "image/jpeg" | "image/webp",
) {
  const res = await client.messages.create({
    model: "claude-haiku-4-5",
    max_tokens: 512,
    output_config: { format: { type: "json_schema", schema: taggingJsonSchema } },
    messages: [
      {
        role: "user",
        content: [
          { type: "image", source: { type: "base64", media_type: mediaType, data: cutoutBase64 } },
          { type: "text", text: PROMPT },
        ],
      },
    ],
  });
  const text = res.content.find((b) => b.type === "text")?.text ?? "{}";
  return parseTagText(text); // validated Tags (a draft shown on the confirm screen)
}

import { COLORS } from "@/lib/closet/vocab";

/**
 * Derived from the palette, never hand-listed.
 *
 * The old literal set carried `khaki`, `ecru` and `gray` — none of which the
 * picker can produce — and omitted `camel`, `denim` and `silver`, which it can.
 * With `TagSchema.colors` now a `z.enum`, the palette is the only vocabulary
 * that exists, so both lists here are computed from it and a test pins that
 * every name they contain is a real colour.
 */
export const NEUTRAL_NAMES: string[] = COLORS.filter((c) => c.neutral).map((c) => c.name);

const NEUTRALS = new Set<string>(NEUTRAL_NAMES);

export function isNeutral(color: string): boolean {
  return NEUTRALS.has(color.trim().toLowerCase());
}

/** 1.0 = all neutral; each accent beyond the first costs 0.25. */
export function colorHarmonyScore(colors: string[]): number {
  const accents = colors.filter((c) => !isNeutral(c)).length;
  const penalty = Math.max(0, accents - 1) * 0.25;
  return Math.min(1, Math.max(0, 1 - penalty));
}

/**
 * The Refine "Lean into" palette — the five swatches in `refine-sheet.tsx`.
 *
 * The swatches are families, not literal tag values: `neutral` and `dark` are
 * categories, and matching a swatch id verbatim would find nothing for them.
 *
 * These lists used to carry ~23 free-form names (sand, oatmeal, taupe, cognac,
 * terracotta, cobalt, sage, onyx…) because Haiku emitted colours off any
 * vocabulary. That was the right answer while `colors` was `z.string()`; now the
 * schema is a `z.enum` over the palette, so any name outside it is dead weight
 * that can never match. A test asserts every member is a real palette colour.
 *
 * NOT a partition, on purpose. Families overlap (`tan` is both neutral and
 * camel), and `pink` and `yellow` belong to none — leaning on "camel" simply
 * does not favour a pink shirt, which is correct. `leanScore` is a weighted
 * term, never a filter, so an unfamilied colour is not excluded from anything.
 */
export const COLOR_FAMILIES: Record<string, string[]> = {
  neutral: ["white", "ivory", "cream", "stone", "sand", "beige", "taupe", "grey", "silver"],
  camel: ["camel", "tan", "caramel", "chocolate", "brown", "rust", "terracotta", "gold"],
  navy: ["navy", "indigo", "denim", "blue", "sky", "teal"],
  olive: ["olive", "khaki", "sage", "forest", "green", "mint"],
  dark: ["black", "charcoal", "burgundy", "maroon", "plum"],
};

export function inFamily(color: string, family: string): boolean {
  return COLOR_FAMILIES[family]?.includes(color.trim().toLowerCase()) ?? false;
}

/**
 * How well a combo answers the user's "Lean into" picks: the fraction of the
 * requested families that appear somewhere in the outfit.
 *
 * Returns 1 for an empty request so callers can score unconditionally — asking
 * for nothing is never a penalty.
 */
export function leanScore(colors: string[], families: string[]): number {
  if (!families.length) return 1;
  const hits = families.filter((f) => colors.some((c) => inFamily(c, f))).length;
  return hits / families.length;
}
===== SCORE
import { colorHarmonyScore, leanScore } from "./color";
import { seasonFit } from "./season";
import { warmthFit } from "./texture";

export type ScoreItem = {
  category: string;
  colors: string[];
  formality: number | null;
  style_tags?: string[];
  seasons?: string[];
  /** "solid" | "striped" | "check" | "print" | "other". Null = no opinion. */
  pattern?: string | null;
  /** Fibre and construction. Together they carry warmth — see ./texture.ts. */
  material?: string | null;
  texture?: string | null;
};
export type Ctx = {
  aesthetic: string[];
  band: [number, number];
  /** Refine "Lean into" colour families. Empty = no preference. */
  lean?: string[];
  /**
   * Item ids from the set a regenerate is replacing. A SOFT preference applied
   * in `rankTopN`, never a filter: pieces sink in the ranking but are never
   * removed from the closet, so a small wardrobe still returns its one good
   * outfit instead of an empty screen.
   */
  recentlyShown?: string[];
  /** The current season ("Winter"). Absent = no season preference at all. */
  season?: string;
  /**
   * Today's temperature. Absent = no thermal reading, so the climate term falls
   * back to the season tag alone. Threaded from the forecast the generator
   * already fetches.
   */
  tempC?: number;
};

/**
 * How much of the score the colour lean is allowed to claim when one is asked
 * for. High enough to reorder the top 20 decisively, low enough that a combo
 * missing the colour still beats an incoherent one that has it — the lean is a
 * preference, never an eliminator.
 */
const LEAN_WEIGHT = 0.3;

/**
 * Climate — "does this suit the weather?" — is ONE term, not two.
 *
 * Season and warmth answer the same question with different evidence, so they
 * share a weight instead of competing for the score. Adding warmth as a third
 * independent preference would have pushed the total past 0.5 and squeezed
 * colour, formality and DNA below half whenever a Refine lean was also active;
 * merging keeps the budget bounded by construction and gives weather a single,
 * better-informed vote. Future weather work (wind, humidity) belongs inside
 * this term, not beside it.
 *
 * Slightly above the 0.2 season alone used to carry — the term now reads a real
 * temperature rather than only the month — and still low enough that an
 * off-season combo which actually works beats an in-season mess.
 */
const CLIMATE_WEIGHT = 0.28;

/**
 * Within climate, how much of the vote the thermometer gets over the tag.
 *
 * Warmth leads because it reads today's temperature against this garment's
 * fibre and construction, where `seasons` is a coarse, user-editable proxy
 * that no closet fills in reliably. The tag keeps a real share because it
 * carries what fabric cannot say — a linen suit is Summer, a Christmas jumper
 * is December — and because it is the only climate signal left when a forecast
 * fails.
 */
const WARMTH_SHARE = 0.7;

/** 1.0 = identical formality; falls off with spread. */
export function formalityCoherence(formalities: number[]): number {
  const f = formalities.filter((x) => typeof x === "number");
  if (f.length < 2) return 1;
  const spread = Math.max(...f) - Math.min(...f);
  return Math.max(0, 1 - spread / 4); // spread of 4 (1↔5) → 0
}

/**
 * One patterned piece is a statement; two are an argument.
 *
 * Counts non-solid pieces: 0 or 1 is clean, each additional one costs. Floored
 * well above zero because a wardrobe of patterned shirts must still be
 * dressable — the same rule every other signal in this file follows.
 */
export function patternHarmony(patterns: (string | null | undefined)[]): number {
  const loud = patterns.filter((p) => p && p !== "solid").length;
  return loud <= 1 ? 1 : Math.max(0.3, 1 - (loud - 1) * 0.35);
}

/**
 * How well the combo suits today, on whichever evidence exists.
 *
 * Returns null when there is neither a temperature nor a season, so the caller
 * can drop the term entirely rather than fold in a meaningless 0.5.
 */
function climateFit(items: ScoreItem[], ctx: Ctx): number | null {
  const warmth = ctx.tempC == null ? null : warmthFit(items, ctx.tempC);
  const season = ctx.season ? seasonFit(items, ctx.season) : null;
  if (warmth == null) return season;
  if (season == null) return warmth;
  return WARMTH_SHARE * warmth + (1 - WARMTH_SHARE) * season;
}

export function scoreCombo(items: ScoreItem[], ctx: Ctx): number {
  const colors = items.flatMap((i) => i.colors);
  const harmony = colorHarmonyScore(colors);
  const coherence = formalityCoherence(items.map((i) => i.formality ?? 3));
  const dnaHits = items.filter((i) => i.style_tags?.some((t) => ctx.aesthetic.includes(t))).length;
  const dna = items.length ? dnaHits / items.length : 0;
  const pattern = patternHarmony(items.map((i) => i.pattern));
  const base = 0.4 * harmony + 0.3 * coherence + 0.15 * dna + 0.15 * pattern;

  // Each preference claims its weight only when it applies, so with neither one
  // set the score is byte-identical to what it was before either landed.
  const climate = climateFit(items, ctx);
  const wl = ctx.lean?.length ? LEAN_WEIGHT : 0;
  const wc = climate == null ? 0 : CLIMATE_WEIGHT;
  return Math.min(
    1,
    base * (1 - wl - wc) + wl * leanScore(colors, ctx.lean ?? []) + wc * (climate ?? 0),
  );
}

import type { UiOccasion } from "./types";

export type Weather = {
  /** The temperature RIGHT NOW. Display, and the fallback when no day range exists. */
  tempC: number;
  rain: boolean;
  /**
   * Today's high and low.
   *
   * The daily drop is generated once and worn all day, so scoring against
   * `tempC` optimises for the minute the user happened to open the app. On
   * 2026-08-14 that produced a cable-knit sweater at 07:45 for a day that
   * reached 34.8°C. **The look is built for the HIGH; the cold end of the day is
   * handled by advice, not by the outfit** — otherwise a 22°-afternoon /
   * 9°-morning day puts a coat in every flat-lay you see at 3pm.
   *
   * Optional: fixtures and any caller without a forecast fall back to `tempC`.
   */
  highC?: number;
  lowC?: number;
};

/** The temperature the LOOK is built for. */
export function planningTemp(w: Weather): number {
  return w.highC ?? w.tempC;
}

// v2 UI occasions → formality bands (Decision D9, widened — see below).
//
// An occasion is CONTEXT, not a dress code. "Evening" covers both a casual date
// and a black-tie dinner; "Work" covers both a creative studio in sneakers and a
// boardroom. What separates them is the user's dress code, which onboarding
// already collects (profiles.formality_min/max) and personalBand() applies.
// Narrow per-occasion bands used to encode one assumed dress code for everyone,
// which left a smart-casual wardrobe unable to produce a Work or Evening outfit
// at all. Every band now includes 3 (smart casual) — a legitimate answer anywhere.
const BANDS: Record<UiOccasion, [number, number]> = {
  everyday: [1.5, 3],
  work: [2, 4.5],
  weekend: [1, 3.5],
  evening: [2.5, 5],
};

export function occasionBand(o: UiOccasion): [number, number] {
  return BANDS[o];
}

export type DressCodeRange = {
  formality_min?: number | null;
  formality_max?: number | null;
};

/**
 * The occasion band narrowed to the dress codes the user picked in onboarding
 * (`profiles.formality_min/max`, derived from `dress_codes`).
 *
 * This is the answer the quiz already collects and the generator previously
 * ignored: someone who said "Smart casual" was still asked for 3.5–5 on Evening
 * and got nothing. Padded by ±0.5 so a single dress code isn't a knife-edge, and
 * falls back to the plain occasion band when there's no overlap at all (e.g. a
 * black-tie-only wardrobe asking for Everyday) — better a slightly-off outfit
 * than none.
 */
export function personalBand(
  o: UiOccasion,
  profile?: DressCodeRange | null,
): [number, number] {
  const [olo, ohi] = occasionBand(o);
  const min = profile?.formality_min;
  const max = profile?.formality_max;
  if (min == null || max == null) return [olo, ohi];

  const lo = Math.max(olo, Math.max(1, min - 0.5));
  const hi = Math.min(ohi, Math.min(5, max + 0.5));
  return lo > hi ? [olo, ohi] : [lo, hi];
}

/**
 * An explicit Refine formality (1..5) REPLACES the band with that level ±1.
 *
 * It replaces rather than intersects because Refine is an explicit instruction:
 * previously it was capped at the occasion's ceiling, so a smart-casual profile
 * could never ask for a black-tie outfit no matter what it selected.
 */
export function applyFormalityOverride(
  band: [number, number],
  f: number | null,
): [number, number] {
  if (f == null) return band;
  return [Math.max(1, f - 1), Math.min(5, f + 1)];
}

/**
 * Fabrics that are wrong in real heat NO MATTER HOW THEY ARE MADE.
 *
 * This is the measured replacement for the season tag's incidental thermal
 * protection: season used to be a hard filter, so a sweater tagged
 * {Autumn,Winter} could never reach a July outfit. Season is now a preference
 * (see ./season.ts), so the guard moved to the temperature we already fetch.
 *
 * The list is deliberately SHORT, and notably does not contain wool.
 * Whether a wool garment suits 30°C is decided by its weight and weave, not its
 * fibre: tropical, fresco and high-twist wools are summer suiting, and merino is
 * used *for* heat because it wicks and breathes. `items.material` is a bare
 * fibre name today, so a "wool" rule cannot tell a summer-weight trouser from a
 * melton coat — it would exclude exactly the smart-casual work wear this app is
 * built around. Everything left here is insulation or a coarse heavy weave,
 * where no construction makes it summer-appropriate.
 *
 * Wool, merino and cashmere are not unprotected: an off-season piece still takes
 * the `seasonFit` penalty in scoring, so it ranks below linen in July. Demoted
 * on evidence rather than eliminated on a guess — the same argument this module
 * makes about season itself.
 *
 * That fix has now landed. Warmth is a SCORED signal — `lib/generator/texture.ts`
 * reads material × texture against the real temperature — so this list is no
 * longer where warmth is decided. What remains is only what must never reach a
 * hot day at all: a soft term demotes, and `diversify` still fills 20 shortlist
 * slots, so without this a down jacket can surface at 32°C. There is a real
 * difference between *slightly off-season*, which this project deliberately
 * accepts, and *physically wrong*. `eligibleByCategory`'s relief rule keeps it
 * safe — this can narrow a required slot but can never empty one.
 *
 * `tweed` left with that change: its warmth now lives in `MATERIAL_WARMTH`, so
 * a tweed jacket is scored down in heat rather than banned outright — the same
 * treatment wool already gets, and for the same reason. `quilted` and `puffer`
 * left because neither ever matched: `Quilted` is a TEXTURE, and `puffer` is in
 * no vocabulary at all. They had been dead since `material` became an enum.
 */
const HOT_MATERIALS = ["fleece", "shearling", "down"];

/** Strictly above 25: 24° is pleasant, 26° is hot. */
const HOT_C = 25;

/**
 * Below this the LOOK carries outerwear.
 *
 * Exported because `laterAdvice` needs the same number: the advice strip must
 * never tell you to take a layer the flat-lay already contains. Two copies of
 * 15 would drift, and the drift would be invisible — the sentence would simply
 * start disagreeing with the picture beside it.
 */
export const OUTERWEAR_C = 15;

/** Materials rain ruins. Turned off by the rain-guard preference, nothing else. */
const WET_MATERIALS = ["suede", "canvas"];

/**
 * Above this, a garment's computed warmth stops being a penalty and becomes a bar.
 *
 * `HOT_MATERIALS` only catches insulation by FIBRE, which is why a cotton
 * cable-knit sweater reached a 34.8°C day on 2026-08-14. Measured on the real
 * 21-item closet: the warmth term demoted that combo from #13 to #22 of 66, but
 * `diversify` fills 20 shortlist slots out of 66 combos — so 30% of everything
 * reaches the model and a demotion changes nothing. This is the hole the plan
 * named: *"a soft term demotes, and diversify still fills 20 slots."*
 *
 * Safe as a hard rule because it reads `itemWarmth`, which now respects the
 * wearer's own season tags — a Summer-tagged cable knit is 0.55 and survives,
 * an Autumn/Winter one is 0.65 and does not — and because
 * `eligibleByCategory`'s relief rule guarantees it can narrow a required slot
 * but never empty one.
 */
const SWELTERING_C = 28;
const SWELTERING_MAX_WARMTH = 0.6;

/**
 * @param prefs `rainGuard` is the settings toggle. It defaults ON: the
 * protective behaviour shipped before the switch existed, so an absent
 * preference must preserve it rather than opt the whole userbase out.
 *
 * The toggle reaches the WET list only. The heat exclusions are about comfort
 * at 30°, not about keeping shoes dry, and `needsOuterwear` is about cold — a
 * switch labelled "never suede in the rain" has no business touching either.
 *
 * Everything thermal here reads `planningTemp` — the day's HIGH — not the
 * current temperature. Rain is the exception: it is read from `rain`, which is
 * about the hour you step outside.
 */
export function weatherRules(w: Weather, prefs?: { rainGuard?: boolean }) {
  const rainGuard = prefs?.rainGuard ?? true;
  const planning = planningTemp(w);
  return {
    needsOuterwear: planning < OUTERWEAR_C,
    excludeMaterials: [
      ...(w.rain && rainGuard ? WET_MATERIALS : []),
      ...(planning > HOT_C ? HOT_MATERIALS : []),
    ],
    /** null = warmth is a preference today, as it is on all but the hottest days. */
    maxWarmth: planning > SWELTERING_C ? SWELTERING_MAX_WARMTH : null,
  };
}

