/**
 * Rated material and texture pairings, with the REASON attached.
 *
 * The reason code is not decoration. It is what lets the rerank prompt say
 * *why* a combination was demoted — "linen and flannel contradict each other
 * climatically" is a sentence a user learns from; "rated 1" is not. It also
 * makes a wrong rating diagnosable: a mis-tagged SEA is a different bug from a
 * mis-tagged FORM.
 *
 * SEA = season conflict · FORM = formality/register conflict · WT = weight/bulk
 * conflict · SHN = sheen/finish conflict · TX = same-but-different texture clash
 * · CPX = deliberate contrast, used on purpose (the one POSITIVE code).
 *
 * ⚠️ Ratings assume TWO SEPARATE GARMENTS in one outfit, never a fibre blend
 * inside one garment. `items.material` is the dominant fibre of one piece, which
 * is exactly the unit these ratings compare.
 *
 * ⚠️ Synthesis, not transcription — same standing caveat as `pairing-ratings.ts`.
 * Absent means unresearched; the caller drops the term.
 *
 * Source: `docs/research/fit-check-research-round2-raw.md` §E.
 */
export type ReasonCode = "SEA" | "FORM" | "WT" | "SHN" | "TX" | "CPX";
type Pairing = { rating: number; codes: ReasonCode[] };

export const MATERIAL_PAIRINGS: Record<string, Pairing> = {
