  "Fine knit|Quilted": { rating: 4, codes: ["CPX"] },
  "Chunky knit|Quilted": { rating: 2, codes: ["WT"] },
  "Brushed|Quilted": { rating: 4, codes: ["CPX"] },
  "Flat|Terry": { rating: 3, codes: ["FORM"] },
  "Terry|Twill": { rating: 3, codes: ["FORM"] },
  "Flat|Waffle": { rating: 4, codes: ["CPX"] },
  "Ribbed|Waffle": { rating: 4, codes: ["CPX"] },
  "Herringbone|Herringbone": { rating: 2, codes: ["TX"] },
  "Pile|Pile": { rating: 4, codes: ["CPX"] },
  "Fleece-back|Flat": { rating: 4, codes: [] },
  "Flat|Twill": { rating: 4, codes: [] },
  "Flat|Open knit": { rating: 3, codes: [] },
  // Seersucker's whole function is keeping cloth off the body — the opposite of
  // what a heavy winter texture is for.
  "Quilted|Seersucker": { rating: 1, codes: ["SEA", "WT"] },
  "Chunky knit|Seersucker": { rating: 1, codes: ["SEA", "WT"] },
};

function key(a: string, b: string): string {
  return [a.trim(), b.trim()].sort().join("|");
}

export function materialPairing(a: string, b: string): Pairing | null {
  return MATERIAL_PAIRINGS[key(a, b)] ?? null;
}
export function texturePairing(a: string, b: string): Pairing | null {
  return TEXTURE_PAIRINGS[key(a, b)] ?? null;
}

function meanRating(values: string[], lookup: (a: string, b: string) => Pairing | null): number | null {
  const seen = [...new Set(values.filter(Boolean))];
  const rated: number[] = [];
  for (let i = 0; i < seen.length; i++) {
    for (let j = i + 1; j < seen.length; j++) {
      const p = lookup(seen[i], seen[j]);
      if (p) rated.push(p.rating);
    }
  }
  if (!rated.length) return null;
  return rated.reduce((x, y) => x + y, 0) / rated.length / 5;
}

export function materialScore(materials: string[]): number | null {
  return meanRating(materials, materialPairing);
}
export function textureScore(textures: string[]): number | null {
  return meanRating(textures, texturePairing);
}

/** Every reason code a combo triggered — the raw material for the "why" sentence. */
export function pairingReasons(materials: string[], textures: string[]): ReasonCode[] {
  const codes = new Set<ReasonCode>();
  const collect = (values: string[], lookup: (a: string, b: string) => Pairing | null) => {
    const seen = [...new Set(values.filter(Boolean))];
    for (let i = 0; i < seen.length; i++)
      for (let j = i + 1; j < seen.length; j++)
        for (const c of lookup(seen[i], seen[j])?.codes ?? []) codes.add(c);
  };
  collect(materials, materialPairing);
  collect(textures, texturePairing);
  return [...codes];
}
```

⚠️ `"Chunky knit|Chunky knit"` and `"Herringbone|Herringbone"` are same-value keys on purpose — the research's rule is that two *similar* textures clash where two different ones do not. `meanRating` de-duplicates its input, so these only fire when the caller passes the value twice from two different garments. Verify that behaviour is what the test asserts before changing either.

