```typescript
/**
 * Footwear formality from upper material and sole bulk.
 *
 * The research gives an explicit ranked hierarchy: patent leather 5 · smooth
 * calfskin on a slim sole 4 · double leather sole 3.5 ("bulk adds bulk and
 * reduces formality") · suede/nubuck 3 · rubber or crepe 2 · canvas upper on a
 * vulcanised sole 1. Bulk is a real term in that ladder, not a modifier we
 * invented — which is why plan 2 records it.
 */
const UPPER_BASE: Record<string, number> = {
  Leather: 4, "Faux leather": 3, Suede: 3, Canvas: 1, Rubber: 2, Nylon: 1, Polyester: 1,
};
const BULK_PENALTY: Record<string, number> = { "Low profile": 0, Regular: 0.5, Chunky: 1.5 };

export function soleFormality(material: string, bulk: string | null): number {
  const base = UPPER_BASE[material] ?? 2;
  return Math.max(1, base - (BULK_PENALTY[bulk ?? "Regular"] ?? 0.5));
}

/**
 * Whether a shoe may sit against a given tailoring material.
 *
 * ⚠️ The research's most useful asymmetry, and the reason this is a function
 * rather than a flat rating: rubber-soled and technical sneakers fail against
 * FORMAL WORSTED WOOL, but score fine against linen, cotton or seersucker
 * suiting — *the same shoe*, judged by what it is standing next to. A flat
 * "sneakers are formality 1" rule would wrongly ban the smart-casual linen
 * outfit this app is largely built around.
 *
 * `hard: true` means it filters. Reserved for the worsted-wool case only.
 */
const RELAXED_SUITING = new Set(["Linen", "Cotton", "Canvas", "Denim", "Corduroy"]);
const FORMAL_SUITING = new Set(["Wool", "Merino wool", "Cashmere", "Silk", "Tweed"]);

export function soleAgainstTailoring(
  soleMaterial: string,
  bulk: string | null,
  counterpartMaterial: string,
): { ok: boolean; hard: boolean } {
  const isAthletic = soleFormality(soleMaterial, bulk) <= 1.5;
  if (!isAthletic) return { ok: true, hard: false };
  if (RELAXED_SUITING.has(counterpartMaterial)) return { ok: true, hard: false };
  if (FORMAL_SUITING.has(counterpartMaterial)) return { ok: false, hard: true };
  return { ok: true, hard: false };
}
```

