```typescript
import { soleFormality } from "./styling/footwear";

/**
 * Which styling tradition this combo belongs to.
 *
 * ⚠️ A property of the COMBO, never of the user. One person owns a suit and owns
 * Jordans and wears both; a profile flag would be wrong half the time.
 *
 * Signal priority is the research's, not ours: footwear category is the
 * strongest and is checked first; branding is second; proportion third and
 * unreliable at tier 3 where the registers converge; monochrome is never used
 * standalone and so is not used here at all.
 *
 * ⚠️ The gaming objection — drop a hoodie in and the sneaker penalty
 * evaporates — is answered by requiring an ANCHOR, not merely a gap. A big
 * formality gap with no streetwear anchor present (dress shirt and gym shorts,
 * no sneaker, no branding, no oversized cut) stays a mistake in both frames.
 */
export type Frame = "classic" | "streetwear";
export type FrameItem = {
  category: string;
  material?: string | null;
  branding?: string | null;
  fit?: string | null;
  formality?: number | null;
  bulk?: string | null;
};

export function detectFrame(items: FrameItem[]): Frame {
  // ⚠️ Checked BEFORE every other signal. Streetwear's tier-5 cell is empty —
  // "formal streetwear" denotes elevated dressy-casual, not black tie — so once
  // anything in the outfit is genuinely formal, the classic rules are the only
  // ones that exist to apply.
  if (items.some((i) => (i.formality ?? 0) >= 5)) return "classic";

  // 1. Footwear — the strongest signal.
  const shoes = items.find((i) => i.category === "Shoes");
  if (shoes) {
    const f = soleFormality(shoes.material ?? "Leather", shoes.bulk ?? null);
    if (f <= 1.5) return "streetwear"; // athletic/vulcanised
    if (f >= 3.5) return "classic"; // dress shoe
    // 2–3.5 is genuinely ambiguous; fall through to the tie-breakers.
  }

  // 2. Branding scale.
  if (items.some((i) => i.branding === "Large")) return "streetwear";

  // 3. Proportion — third, and the research warns it is unreliable at tier 3
  // where both registers converge on a moderate fit. Only the extreme counts.
  if (items.some((i) => i.fit === "Oversized" || i.fit === "Relaxed")) return "streetwear";

  return "classic";
}
```

