- [ ] **Step 3: Write minimal implementation**

```typescript
import type { Frame } from "../frame";
import { soleAgainstTailoring } from "./footwear";

/**
 * Rules as data, with their evidence tier attached.
 *
 * ⚠️ The tag is ENFORCED, not documented. `applyRules` decides what a rule may
 * do from its tag alone: HARD excludes, STRONG and PREFERENCE weight, and
 * CONTESTED is structurally incapable of doing either — its weight is asserted
 * to be zero by a test. That is the point. The research asks the engine not to
 * silently resolve a live disagreement, and a comment saying so would not
 * survive the first person in a hurry.
 *
 * ⚠️ Be stingy with HARD. Every hard rule can empty a small wardrobe and leave a
 * real person with no outfit at all.
 */
export type RuleTag = "HARD" | "STRONG" | "PREFERENCE" | "CONTESTED";

export type RuleItem = {
  category: string;
  colors: string[];
  material?: string | null;
  formality?: number | null;
  branding?: string | null;
  bulk?: string | null;
};
export type RuleCtx = { frame: Frame; items: RuleItem[] };

export type Rule = {
  id: string;
  tag: RuleTag;
  frames: Frame[];
  weight?: number;
  /** True when the rule is VIOLATED. */
  test: (ctx: RuleCtx) => boolean;
  /** Shown in the "why", and sent to the model for CONTESTED rules. */
  because: string;
};

const brandedCount = (items: RuleItem[]) => items.filter((i) => i.branding === "Large").length;
const distinctColours = (items: RuleItem[]) =>
  new Set(items.flatMap((i) => i.colors.map((c) => c.toLowerCase()))).size;

export const RULES: Rule[] = [
  {
    id: "athletic-sole-vs-formal-tailoring",
    tag: "HARD",
    frames: ["classic"],
    because: "an athletic sole does not sit against formal worsted tailoring",
    test: ({ items }) => {
      const shoe = items.find((i) => i.category === "Shoes");
      if (!shoe) return false;
      return items.some(
        (other) =>
          other !== shoe &&
          soleAgainstTailoring(shoe.material ?? "Leather", shoe.bulk ?? null, other.material ?? "").hard,
      );
    },
  },
  {
    id: "sneaker-at-formal",
    tag: "HARD",
    // ⚠️ The ONE shoe rule that holds in BOTH frames — streetwear has no tier-5
    // register at all, so there is no frame in which this is correct.
    frames: ["classic", "streetwear"],
    because: "a sneaker does not belong with formal evening wear in any tradition",
    test: ({ items }) => {
      const shoe = items.find((i) => i.category === "Shoes");
      if (!shoe) return false;
      const athletic = (shoe.material === "Canvas" || shoe.bulk === "Chunky");
      return athletic && items.some((i) => (i.formality ?? 0) >= 5);
    },
  },
  {
    id: "logomania",
    tag: "HARD",
    frames: ["classic", "streetwear"],
    because: "four or more loud logos stop communicating anything",
    test: ({ items }) => brandedCount(items) >= 4,
  },
  {
    id: "three-loud-logos",
    tag: "STRONG",
    frames: ["classic", "streetwear"],
    weight: 0.3,
    because: "three loud logos is past the point where the outfit reads intentional",
    test: ({ items }) => brandedCount(items) === 3,
  },
  {
    id: "colour-ceiling",
    tag: "HARD",
    frames: ["classic", "streetwear"],
    because: "three colours is the reliable upper limit for one outfit",
    test: ({ items }) => distinctColours(items) > 3,
  },
  {
    id: "black-with-navy",
    tag: "CONTESTED",
    frames: ["classic", "streetwear"],
    because:
      "black with navy: traditionally avoided, but current sources accept it when texture or pattern separates the two — judge it in this outfit",
    test: ({ items }) => {
      const c = new Set(items.flatMap((i) => i.colors.map((x) => x.toLowerCase())));
      return c.has("black") && c.has("navy");
    },
  },
  {
    id: "black-with-brown",
    tag: "CONTESTED",
    frames: ["classic", "streetwear"],
    because:
      "black with brown: contested — it works via charcoal substitution, heavy winter fabric, or keeping brown to outerwear and accessories",
    test: ({ items }) => {
      const c = new Set(items.flatMap((i) => i.colors.map((x) => x.toLowerCase())));
      return c.has("black") && (c.has("brown") || c.has("chocolate"));
    },
  },
];

/**
 * Apply every in-frame rule, in the precedence the spec sets out.
 *
 * The ORDER is the contract: HARD rules exclude before any weight is computed,
 * so a combo that should not exist never competes on points.
 */
export function applyRules(ctx: RuleCtx) {
  const live = RULES.filter((r) => r.frames.includes(ctx.frame) && r.test(ctx));

  const excluded = live.some((r) => r.tag === "HARD");
  const contested = live.filter((r) => r.tag === "CONTESTED").map((r) => r.because);
  // CONTESTED can never reach these two lines — `weight` is undefined for them
  // and a test pins it — but the filter is explicit so the guarantee is visible.
  const penalty = live
    .filter((r) => r.tag === "STRONG")
    .reduce((sum, r) => sum + (r.weight ?? 0), 0);
  const bonus = live
    .filter((r) => r.tag === "PREFERENCE")
    .reduce((sum, r) => sum + (r.weight ?? 0), 0);

  return {
    excluded,
    penalty,
    bonus,
    reasons: live.filter((r) => r.tag !== "CONTESTED").map((r) => r.because),
    contested,
  };
}
```

